"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["50249"],{40082(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.termo_consentimento.revisao_sem_base_legal","status":422,"titulo":"Rascunho sem base legal n\xe3o pode ser marcado como revisado nem promovido"},"descricao":{"codigo":"uniplus.configuracao.termo_consentimento.revisao_sem_base_legal","requisitos":["UNI-REQ-0086"],"oQueAconteceu":["A revis\xe3o institucional \xe9 a verifica\xe7\xe3o que antecede a promo\xe7\xe3o do rascunho a vers\xe3o do termo, e s\xf3 se marca um rascunho que tenha texto e base legal (UNI-REQ-0086). O pedido (`POST /api/configuracao/admin/termos-consentimento/{id}/revisar`) chegou para um termo cujo rascunho tem texto, mas est\xe1 sem base legal, vazia ou s\xf3 com espa\xe7os. A forma de aceite n\xe3o \xe9 exigida nesta etapa: ela pode continuar em `A_DEFINIR` at\xe9 a publica\xe7\xe3o de um processo.","A busca do termo vem antes: com um `{id}` que n\xe3o existe, a resposta \xe9 a de termo n\xe3o encontrado (`uniplus.configuracao.termo_consentimento.nao_encontrado`). O texto \xe9 conferido antes da base legal: sem texto, a recusa \xe9 `uniplus.configuracao.termo_consentimento.revisao_sem_texto`. Nada \xe9 gravado.","A promo\xe7\xe3o de um rascunho sem base legal n\xe3o chega a esta confer\xeancia: ela exige a revis\xe3o antes, e a revis\xe3o n\xe3o \xe9 marcada sem base legal (`uniplus.configuracao.termo_consentimento.promocao_sem_revisao`)."],"comoResolver":["Informe a base legal do rascunho, com at\xe9 500 caracteres (`PUT /api/configuracao/admin/termos-consentimento/{id}/rascunho`, com o texto, a base legal e a forma de aceite), e pe\xe7a a revis\xe3o de novo."],"ondeAparece":["Marca\xe7\xe3o do rascunho de um termo de consentimento como revisado"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Termo consentimento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);